import{_ as i,c as o,o as t,aj as l}from"./chunks/framework.lC5GZWV9.js";const f=JSON.parse('{"title":"Jellyfin Sink","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/jellyfin-sink.md","filePath":"integrations/jellyfin-sink.md","lastUpdated":1791012380000}'),a={name:"integrations/jellyfin-sink.md"};function n(d,e,r,s,c,h){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="jellyfin-sink" tabindex="-1">Jellyfin Sink <a class="header-anchor" href="#jellyfin-sink" aria-label="Permalink to “Jellyfin Sink”">​</a></h1><p>Automatically add new <a href="https://jellyfin.org" target="_blank" rel="noreferrer">Jellyfin</a> movie and show plays to Ryot. It will work for all the media that have a valid TMDb ID (or TVDB ID, if selected in the integration settings) attached to their metadata.</p><p>Two kinds of webhook plugins are supported and detected automatically:</p><ul><li><a href="https://github.com/jellyfin/jellyfin-plugin-webhook" target="_blank" rel="noreferrer">Official webhook plugin</a> (available in the Jellyfin plugin catalog)</li><li><a href="https://github.com/shemanaev/jellyfin-plugin-webhooks" target="_blank" rel="noreferrer">Unofficial webhook plugin</a></li></ul><p>Generate a slug in the integration settings page and copy the newly generated webhook URL. It looks like <code>https://&lt;instance_url&gt;/_i/&lt;slug&gt;</code>.</p><h2 id="official-plugin" tabindex="-1">Official plugin <a class="header-anchor" href="#official-plugin" aria-label="Permalink to “Official plugin”">​</a></h2><ol><li>Install the <code>Webhook</code> plugin from the Jellyfin plugin catalog and restart Jellyfin.</li><li>Go to the plugin settings and add a new <code>Generic</code> destination with the following settings: <ul><li>Webhook URL =&gt; <code>&lt;paste_url_copied&gt;</code></li><li>Request method =&gt; <code>POST</code></li><li>Request content type =&gt; <code>application/json</code> (add a <code>Content-Type</code> header if the destination does not set it automatically)</li><li>Notification types =&gt; <code>PlaybackStart</code> and <code>PlaybackStop</code> (<code>PlaybackProgress</code> is optional, for finer-grained progress)</li><li>Item types =&gt; Enable <code>Movies</code> and <code>Episodes</code></li><li>User filter =&gt; Optionally restrict to your user</li></ul></li><li>Enable the <code>Send all properties</code> option on the destination. Ryot reads the flat payload (<code>NotificationType</code>, <code>ItemType</code>, <code>Provider_tmdb</code>, ticks, ...) directly.</li></ol><h2 id="unofficial-plugin" tabindex="-1">Unofficial plugin <a class="header-anchor" href="#unofficial-plugin" aria-label="Permalink to “Unofficial plugin”">​</a></h2><ol><li>In the Jellyfin webhook plugin settings, add a new webhook using the following settings: <ul><li>Webhook URL =&gt; <code>&lt;paste_url_copied&gt;</code></li><li>Payload format =&gt; <code>Default</code></li><li>Listen to events only for =&gt; Choose your user</li><li>Events =&gt; <code>Play</code>, <code>Pause</code>, <code>Resume</code>, <code>Stop</code> and <code>Progress</code></li></ul></li></ol><h2 id="behavior-notes" tabindex="-1">Behavior notes <a class="header-anchor" href="#behavior-notes" aria-label="Permalink to “Behavior notes”">​</a></h2><ul><li>Only <code>Movie</code> and <code>Episode</code> items are processed, everything else is ignored.</li><li>A TMDb ID is required by default (or a TVDB ID if <code>TVDB</code> is selected as the metadata provider in the integration settings). Supported playback notifications lacking the configured ID fail webhook processing rather than being skipped; this includes items with only an IMDb ID.</li><li>If <code>PlayedToCompletion</code>/<code>Played</code> is set, progress is recorded as 100%.</li><li><code>MarkPlayed</code> events record 100% progress, <code>MarkUnplayed</code> events are ignored.</li><li>If you configured a username in the integration settings, only payloads for that user are processed.</li></ul>',11)])])}const g=i(a,[["render",n]]);export{f as __pageData,g as default};
